CREATE TABLE incident_reactions (incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, reaction text NOT NULL CHECK(reaction IN ('UP','DOWN')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(incident_id,user_id));
CREATE TABLE affected_confirmations (incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(incident_id,user_id));
CREATE TABLE incident_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, author_user_id uuid NOT NULL REFERENCES users(id), parent_comment_id uuid REFERENCES incident_comments(id), body text NOT NULL, moderation_status text NOT NULL DEFAULT 'PUBLISHED', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz);
CREATE TABLE incident_follows (incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(incident_id,user_id));
CREATE TABLE resolution_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), verdict text NOT NULL CHECK(verdict IN ('CONFIRM','DISPUTE')), note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(incident_id,user_id));
CREATE TABLE intervention_expressions_of_interest (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id), organization_id uuid NOT NULL REFERENCES organizations(id), participation_types jsonb NOT NULL, note text, visibility text NOT NULL DEFAULT 'PRIVATE', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE intervention_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES incidents(id), lead_organization_id uuid NOT NULL REFERENCES organizations(id), status text NOT NULL DEFAULT 'DRAFT', payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE intervention_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proposal_id uuid NOT NULL REFERENCES intervention_proposals(id) ON DELETE CASCADE, authority_organization_id uuid REFERENCES organizations(id), approval_type text NOT NULL, status text NOT NULL DEFAULT 'REQUIRED', reason text, required_documents jsonb NOT NULL DEFAULT '[]', conditions text, issued_document_public_id text, issued_at timestamptz, expires_at timestamptz, reviewer_user_id uuid REFERENCES users(id));
CREATE TABLE intervention_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proposal_id uuid NOT NULL REFERENCES intervention_proposals(id) ON DELETE CASCADE, title text NOT NULL, status text NOT NULL DEFAULT 'PENDING', due_date date, details text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), actor_organization_id uuid REFERENCES organizations(id), action text NOT NULL, target_type text NOT NULL, target_id uuid, metadata jsonb NOT NULL DEFAULT '{}', request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_user_id uuid REFERENCES users(id), target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
